) AS (
  VALUES 
    (60::BIGINT, 'Excelente profesora. Es estricta y le gusta los trabajos bien hechos, atiende consultas y da puntos a reclamos, tiene que estudiar el libro y tomar apuntes en clases para que le vaya bien en quiz y exámenes. Si usted es vago y deja todo para lo último NO se matricule con ella porque le va a ir mal'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '1877792203b215ee21b85dcf4bdff1208ab9f859cac74b0916b7ab2985161531'::TEXT, ARRAY[2450, 2455]::BIGINT[]),
    (60::BIGINT, 'La profesora sabe bastante, se nota su formación. Solo que si es muy dura, exámenes largos y a veces las preguntas tiene que analizar bastante, pero si le pone y sale bien en los exámenes podría decir que uno le llega a agradar, adémas si puede y tiene argumentos validos reclámele, eso le gusta'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2026-07-11T00:00:00+00:00'::TIMESTAMPTZ, '0ebbcfb4d8fd66e13bb1926907730f443b47fb9b82c1965dc9d7c23fcc66b508'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Desordenada, perdí un 10% de la nota porque pasó diciendo que no pedía avances... y un día nd más llegó a decir "quiero el avance hoy a las 11am". Matriculen con CUALQUIER otro profesor y verán que ella vuelve un curso sencillo, en un curso dificil.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-06-12T00:00:00+00:00'::TIMESTAMPTZ, '45d1d0c3e88a4da84908af518f3e413663b5063aaf0f17bde191d8e33884e955'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Forma de enseñar desastrosa, me atrevo a decir que eso es un reflejo de su vida personal ya que siempre llega a reventar las tapas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-01-18T00:00:00+00:00'::TIMESTAMPTZ, '5f65143f4d704841debd1dcc9a0564b1a7863ca11bc1487f3ac8ab3ed9e26347'::TEXT, ARRAY[2450, 2455]::BIGINT[]),
    (60::BIGINT, 'muy buena profe es bastante exigente en temas de proyectos y los examenes no son muy complicados pero si largos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '91fd3881b16b22baa0eae3382dbf9ebfeeca00a61a8ccf1eee473acd147d1ea9'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'La profesora es muy problemática, sus instrucciones son confusas y califica de manera arbitraria, esperando que hagamos los trabajos de una manera que ni siquiera ella comprende. Se burla y menosprecia a quienes le hacen reclamos sobre sus calificaciones injustas.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-05-24T00:00:00+00:00'::TIMESTAMPTZ, '7cc70a91ec8c9e6a6c9d2098d2b6a87a76f76cc466081bec0fa87387a19df46f'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Es una profesora que sabe mucho de lo que habla y es ordenada con el cronograma pero: Toca leer demasiado, hace quizzes casi todas las semanas, no pasa las diapositivas, se atrasa con calificaciones, da la materia muy rápido, califica durísimo todo y se tiene que matar para pasar.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '54c83afdf30c65c0ce78ace5652f78c3a35c51dd13d3319dfcbb94fb152daacc'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'No la recomendaría como profesora o profesional, durante clases puede faltarle el respeto a estudiantes basado en clases sociales, raza, forma de vestir o si tienen tatuajes o perforaciones, hace comentarios despectivos. Es muy poco objetiva al calificar, no entrega rúbricas a tiempo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0f1001222295e834e5791d00ca96c9dcc7bb698b37396d6dbeb6afa42d4eb98b'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Profesora bastante estricta pero justa y buena. Los exámenes son a mano, es importante tomar notas en clase. Ha tomado la retroalimentación de los estudiantes y su métrica de evaluación del proyecto es coherente. Si quieres aprender, ve con esta profesora. Te ayuda si ve que eres un buen estudiante'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2024-10-15T00:00:00+00:00'::TIMESTAMPTZ, 'c8e7e491fcab2c612980f3d319ab567c751c66b9e82456ac99f22d90845a5aae'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Si quiere perder el semestre como muchos y pasar aburrido pues matricule con ella . No es clara pero espera mucho de los estudiantes. Las clases no las da ella si no los estudiantes o invitados.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd49b2ad2cacf264f276d79b6ff8ba7e5563755c579bae4d76389a258e8d229dd'::TEXT, ARRAY[2450, 2455]::BIGINT[]),
    (60::BIGINT, 'Excelente profesora, si quiere aprender y conocer la realidad de la profesión, tome clases con ella, porque le va a enseñar.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5a379be99a84db4b2256778b00b613e1932a32060fcc3e1e752e9c33c1086bb5'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4fcb282b3d622157b9cd4f6ecac99efc132b3881f9dcb13751fb2f6e4a5a0e78'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'La profe sabe mucho, le gusta mucho GTH, pero si como estudiante no te gusta esta materia mejor no matricule, es un curso realmente duro, más que todo porque los examenes son presenciales y a mano, entonces esto lo complica bastante. GTH I con ella es mucho más fácil y flexible.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, '3c44f5dd96b259b0c21d218c89e3b0daf65ed90cb3d3aea20a9d03d36b310814'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Si se quieren no matriculen con ella'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-11-03T00:00:00+00:00'::TIMESTAMPTZ, '3514c4531804a97ea7f505e7eec6915d08bb35ff61ea7269fde54e0dfd549519'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Si usted quiere aprender y le gusta el área de RH, meta con esa profe porque a huevo va a aprender, pero sino es de su interés mejor busque otra opción porque es bastante pesado y difícil. Los exámenes son difícil, mete materia que vimos con una semana de tiempo. Califica duro.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, '1df3c80a7496e2a7ad463827cd5c590f7f2c76b976742d2fc86303f8e01f1cbb'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Excelente profesora, sabe mucho y con solo que haga los trabajos tal como lo pide con eso pasa el curso. Eso sí califica durísimo y no tiene piedad'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a48f79ebc902a7eb76dd0df7b1a7324092a7a2ef860b9f9a4d7a658e8bbf9c8a'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Se para, no da instrucciones bien la retroalimentacion que da es una mierda, no lleven con ella de verdad'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3f69b4624e2f69835127a8ccdd03c95a662fc994770d889ee996404fb19d4b45'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Es una buena profesora, como profesional sabe mucho y se esmera por ser entendible en las clases dando ejemplos reales, en cuanto a el proycto busque un buen grupo de trabajo para que pueda pasarlo y intente entender lo que pide en los examenes, caigale bien ya que es mas comprensiva de esa manera.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'bfd1c9cfa2b76ec99681c9d1288389a0b68fc67059ea9bddc8480a3de416dde1'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Clases largas y aburridas. Lee, lee y lee y no explica.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos exámenes']::TEXT[], '2023-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'cf802610f283660a1da45a52f9a6c59cdc3a37914b7b91304da15c66b7b5c008'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'Las instrucciones son super confusas y abiertas a interpretaciones, la profe no aydua, califica duro el proyecto, no da explicaciones o retroalimentacion. Nunca tomaria esa clase con ella de nuevo, NO MATRICULEN con ella...'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0c7a702c15806947a0b6d14ba4ee7bd2a415e4be115d695c8d8c467bcd02b19b'::TEXT, ARRAY[2450, 2455]::BIGINT[]),
    (60::BIGINT, 'Es una muy buena profesora, califica duro pero si el objetivo es aprender, ella es la profesora'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8d1d60add4759f70a3b8818e4cc227139a9ffdd1b05c577a645bf4c513863034'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'd00dc02560855bf93a532f2cf4994a0532407bd19c9b884828275ac236994b6e'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Profesora sumamente exigente, cuesta quedarle bien con algo y es dura para calificar. Las clases son asincrónicas y se nota que sabe bastante y que le dedica tiempo al curso. Pero, es pedante, confusa con las instrucciones y tiene que dedicarle bastante tiempo al proyecto y examenes (grupales)'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '6be8c9ade69e88b8177a9e0c64d8f7d90b9a94c84b90c2600a8247f0f85b2512'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Explica bien pero es aburrida. Califica muy duro todo pero uno aprende. Todos los trabajos y examenes son muy largos y las indicaciones no son claras entonces uno se estresa. Es un poco gruñona. Virtualmente solo sube las presentaciones con audio y deja trabajos. En conclusión es mucho estrés.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '85965e548de8a7629f91d4062dbd188eca92ce1f68200a2f651c0c504e9fe3e1'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Como profesora es muy buena gente y explica bien. El detalle es que califica MUY duro el proyecto. Y tiene el problema que tiende a cambiar las instrucciones o deja abierta la interpretación de las mismas, por tanto, no se le queda bien ahí. Pero por lo demás, si se interesa en el estudiante.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '8a4dcb975c5f87a9784ce566d16562c7ea802bb6de8638296cd6f2d884a9f4fc'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Excelente Profesora, se preocupa mucho por que el estudiante aprenda, las clases son entretenidas, en el proyecto y tareas es estricta pero se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'e619510ed10972fc0061999765eba2611ef4c5bed0c279d23d98f62919685dc6'::TEXT, ARRAY[2450, 2455]::BIGINT[]),
    (60::BIGINT, 'Es excelente para enseñar, califica duro los proyectos pero realmente uno aprende a hacerlos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3af43321edb455e07a4a3766c722ad1c4eb4f7f4859a757daea2e943f6341a38'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Es una profesora con un carácter muy fuerte, le gusta humillar a los estudiantes frente al resto del grupo, no ayuda, quisimos ir a consulta para que nos aconsejara con nuestro avance y ni siquiera quiso verlo, nos dijo que hasta la entrega. Es muy clara para explicar y estricta para calificar.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-04-12T00:00:00+00:00'::TIMESTAMPTZ, '264c3cdce8b7ae24e281f287d899a2f5cedcd564bc72edd48d1a00c1d510e6d6'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Excelentisima profe bastante estricta, examenes fáciles si estudia, deja mucha lectura pero no se siente. Los quices algo duros pero nada del otro mundo. 1000% recomendada'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '56c3e7d3e86c9aa0db0e61303ca212b6b046452565acb32d576cc6c2955f9c0a'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'excelente profe explica muy bien y los exámenes y quizes son fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '29fac9dd787785cd108b1c3ccc969d259682a19497b046a7167a6faa06e966ce'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'Todo es de memoria, lee diapositivas, muy metódica, demasiado simple'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-10-30T00:00:00+00:00'::TIMESTAMPTZ, 'bb1c5962c4b316d4e7a06e580749278e4119c82754f4ebb8b63c14b9aa5028ad'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0b0c166d04179da5ce91cde399e1ac15044baaabc05dfb2286e7e21c6d3f66e1'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2016-06-05T00:00:00+00:00'::TIMESTAMPTZ, '98c9d0ff19917056cf93f1d13e128f055f027a54b7236b581eb59551c9e46141'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'La profe es un amor, estricta pero muy organizada. Es fácil de pasar el curso con ella si cumple con todo lo que asigna.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, '917d1b380210d1dd9959a020d3fbf1c07daa1ce29403daa579c0474a48568d02'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Deja trabajos largos']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'f38ee43107353acce4aa99564291022fd7e6f6e3e7d4cb121459079b77645294'::TEXT, ARRAY[2455]::BIGINT[]),
    (60::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2016-05-18T00:00:00+00:00'::TIMESTAMPTZ, '6fd6021a6384c47acbe3bec64bcb972e9f2e7e3c1d46e7d695f39b8c23270c73'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'Excelente profe! Se ve estricta, pero es un amor de persona y ayuda mucho si ve que ud le pone interés.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'b303f874af6bbd6ef9b3c394282dc78999403616856abafe5598ac6c04b24969'::TEXT, ARRAY[2450, 2455]::BIGINT[]),
    (60::BIGINT, 'Muy teórico pero bastante claro y fácil de pasar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, '76b3b37fa3285e36fe54e35fa5cb70309db247745d091d01fe2fdefb5a0ca820'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'NO ES FÁCIL. SE APRENDE PERO EL CURSO ES DE MUCHA MEMORIA, Y LAS CLASES SON MUY TEDIOSAS Y ABURRIDAS. PARECE UN KARAOKE, SOLO LEE DIAPOSITIVAS. ESTRICTA, PERO SE APRENDE.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'a2ed0d76bf912bcc752878d544d16317276d4d9dac85388823017f4b02e87d18'::TEXT, ARRAY[2450]::BIGINT[]),
    (60::BIGINT, 'Muy estricta,pero una profesora que motiva a entender. Yo la recomiendo hay que ponerle y es facil entonces'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6d62af712ca06078527e845b00b13fe2baa5bfb5f3200b1b7b13041956202dc4'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'No es fácil pasar pero explica muy bien y es estricta'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cb048e44a275ebcf1622953d66c3302caa3835b417d71f1450a2fb6ebc62994d'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (60::BIGINT, 'Teoría 1, exámenes de muchísima memoria, más que todo de conceptos. Teoría 2, utiliza casos para evaluar, exámenes de dos partes individual y grupales. Trabajo Final: Muy estricta, con el formato y la presentación oral.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'd31e162b7120917ed0a4825d1349731c6457e09a569e15a10b1bc67c8caecb63'::TEXT, ARRAY[2450, 2455]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
